构造函数的核心结构：
```cpp
template <typename T>
Matrix<T>::Matrix(std::size_t width, std::size_t height)
{
    m_matrix = new T*[width]{};
    m_width = width;
    m_height = height;

    try {
        for (std::size_t i{0}; i < width; ++i) {
            m_matrix[i] = new T[height];
        }
    } catch (...) {
        std::cerr << "Exception caught in constructor, cleaning up "
                  << std::endl;
        cleanup();
        std::throw_with_nested(std::bad_alloc());
    }
}
```

清理函数的结构：
```cpp
template <typename T>
void Matrix<T>::cleanup()
{
    for (std::size_t i{0}; i < m_width; ++i) {
        delete[] m_matrix[i];
    }
    delete[] m_matrix;
    m_matrix = nullptr;
    m_width = m_height = 0;
}
```
